``f̀rom llama_index.core import VectorStoreIndex, SimpleDirectoryReader, Settings from llama_index.embeddings.huggingface import HuggingFaceEmbedding from llama_index.llms.ollama import Ollama # Edinim kaynaklarının bulunduğu klasörün yolu verilmeli documents = SimpleDirectoryReader("/home/sedat/Masaüstü/arastirmaDeneme/data"). load_data() # Sistemde kullanılacak embeddings modeli verilmeli # https://huggingface.co/spaces/mteb/leaderboard adresinden farklı embedding modelleri bulunabilir Settings.embed_model = HuggingFaceEmbedding(model_name="intfloat/multilinguale5-large",trust_remote_code=True)
```

